#ifndef CACHE_ENUMS_h
#define CACHE_ENUMS_h

#include <cstddef>

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

enum class CacheReplPolicy
{
    LRU,
    SRRIP,
    RAND,
    DRRIP,
    LRU_DEAD_BLOCK
};

inline constexpr bool repl_uses_set_dueling(CacheReplPolicy p)
{
    return p == CacheReplPolicy::DRRIP;
}

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

enum class CacheWritebackPolicy
{
    NORMAL,
    EAGER,
    SSRH
};
/*
 * This is the number of DRAM columns to include into the tag bits (see `indexing.h`)
 * */
extern size_t OPT_SSRH_COLUMN_COUNT;

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

#endif
